use ratatui::{prelude::*, widgets::*}; use crate::app::App; pub fn list<'a>(app:&App, title:&'a str, items:Vec<String>, active:bool)->List<'a>{ let rows:Vec<ListItem>=items.into_iter().map(ListItem::new).collect(); List::new(rows).block(Block::bordered().border_style(if active{app.theme.border()}else{app.theme.inactive_border()}).title(title)).highlight_style(if active{app.theme.selected()}else{app.theme.muted()}).highlight_symbol("› ") }